        "value": {
          "type": "string",
          "description": "浅睡阶段时长",
          "sampleValue": "3小时15分"
        }
      },
      "rem": {
        "label": {
          "type": "string",
          "description": "REM阶段名称",
          "sampleValue": "REM"
        },
        "value": {
          "type": "string",
